{"constraints":[
  {
    "constraint":"主体必须是轨道列车/铁路车辆，而不是航空器、公路车辆或船舶。",
    "polarity":"must_have",
    "variants":[],
    "source":"common_sense"
  },
  {
    "constraint":"该列车的外形必须包含高速列车特有的流线型空气动力学车头，而不是旧式平面车头。",
    "polarity":"must_have",
    "variants":[
      "TGV Sud-Est 的较短流线鼻头",
      "TGV Atlantique/Réseau 的楔形流线鼻头",
      "TGV Duplex/Euroduplex 的长流线鼻头",
      "TGV M 的新一代流线鼻头"
    ],
    "source":"common_sense"
  },
  {
    "constraint":"该列车本身不得出现蒸汽机车特有的外露锅炉、烟囱、活塞连杆或蒸汽排放等特征。",
    "polarity":"must_not_have",
    "variants":[],
    "source":"common_sense"
  }
]}
